create index if not exists idx_lead_state_transitions_contact
  on lead_state_transitions (organization_id, contact_id, seq desc);

-- ============================================================================
-- 0009 â€” mÃ©tricas de 1Âª classe persistidas. Labels SÃ“ com ids/contagens â€” PII
