create index if not exists idx_system_update_runs_dispatched
  on public.system_update_runs (dispatched_at desc);
alter table public.system_version    enable row level security;
alter table public.system_update_runs enable row level security;

-- ---- Ã­ndice Ãºnico parcial: no mÃ¡ximo 1 run "dispatched" por vez (migration 0090) ----
--
-- Dedup defensivo ANTES da constraint (clone com dado inconsistente nÃ£o pode
-- quebrar o update.sh): mantÃ©m sÃ³ a linha "dispatched" mais recente, marca
-- as demais como failed.
with ranked as (
  select id, row_number() over (order by dispatched_at desc) as rn
  from public.system_update_runs
  where status = 'dispatched'
)
update public.system_update_runs
set status = 'failed', finished_at = coalesce(finished_at, now())
where id in (select id from ranked where rn > 1);

create unique index if not exists uniq_system_update_runs_dispatched
  on public.system_update_runs (status)
  where status = 'dispatched';

-- â”€â”€ A rodada conta o que aconteceu com o banco (migration 0276) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- Disputa de lock com o sistema no ar, quantas retentativas, em qual passada o
-- banco fechou. Nulo = o caminho nÃ£o passou pelo banco (nÃ£o medido, e a tela
-- nÃ£o inventa texto para isso).
alter table public.system_update_runs
  add column if not exists disputa_de_banco boolean,
  add column if not exists retentativas_do_banco integer,
  add column if not exists passada_do_banco integer;

comment on column public.system_update_runs.disputa_de_banco is
  'Se a rodada do banco enfrentou disputa de lock com o sistema no ar. Nulo = o caminho nÃ£o passou pelo banco.';
comment on column public.system_update_runs.retentativas_do_banco is
  'Quantas retentativas a rodada do banco gastou antes de fechar (0 = fechou na primeira passada). Nulo = o caminho nÃ£o passou pelo banco.';
comment on column public.system_update_runs.passada_do_banco is
  'Em qual passada a rodada do banco fechou (1 = primeira). Nulo = o caminho nÃ£o passou pelo banco.';

alter table public.system_update_runs
  drop constraint if exists system_update_runs_rodada_do_banco_coerente;
alter table public.system_update_runs
  add constraint system_update_runs_rodada_do_banco_coerente check (
    (
      disputa_de_banco is null
      and retentativas_do_banco is null
      and passada_do_banco is null
    )
    or (
      disputa_de_banco is not null
      and retentativas_do_banco is not null
      and retentativas_do_banco >= 0
      and passada_do_banco is not null
      and passada_do_banco >= 1
      and passada_do_banco >= retentativas_do_banco + 1
    )
  );

