    -- 'zernio_social' (migration 0368) endereÃ§a pelo MESMO `zernio_account_id`:
    -- Ã© o mesmo intermediÃ¡rio, com outra superfÃ­cie de canal.
    (provider in ('zernio', 'zernio_social') and zernio_account_id is not null) or
