-- ---- ConfiguraÃ§Ã£o atÃ´mica do prÃ©-go-live (migration 0218) ----
-- 0218 Â· ConfiguraÃ§Ã£o atÃ´mica do prÃ©-go-live do canal
--
-- `channel_sessions.metadata` tambÃ©m guarda dados de transporte e de operaÃ§Ã£o.
-- Ler o jsonb no servidor, espalhar em memÃ³ria e gravar o objeto inteiro faria
-- dois salvamentos concorrentes apagarem a alteraÃ§Ã£o um do outro. Esta funÃ§Ã£o
-- muda somente as trÃªs chaves que pertencem ao prÃ©-go-live, numa instruÃ§Ã£o.

create or replace function public.fn_configurar_pre_go_live_canal(
  p_org uuid,
  p_canal uuid,
  p_modo text,
  p_numeros text[]
)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_linhas integer;
  v_gate text;
begin
  if p_modo is null or p_modo not in ('open', 'pre_go_live') then
    raise exception 'modo de acesso da IA invÃ¡lido' using errcode = '22023';
  end if;

  if p_numeros is null or exists (
    select 1
      from unnest(p_numeros) as n(numero)
     where numero is null or numero !~ '^\+[1-9][0-9]{7,14}$'
  ) then
    raise exception 'lista de telefones de teste invÃ¡lida' using errcode = '22023';
  end if;

  v_gate := case when p_modo = 'pre_go_live' then 'allowlist' else 'open' end;

  update public.channel_sessions
     set metadata = jsonb_set(
       jsonb_set(
         jsonb_set(coalesce(metadata, '{}'::jsonb), '{ai_gate}', to_jsonb(v_gate), true),
         '{ai_gate_mode}', to_jsonb('pre_go_live'::text), true
       ),
       '{ai_test_phone_numbers}', to_jsonb(p_numeros), true
     )
   where organization_id = p_org
     and id = p_canal
     and archived_at is null;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$$;

revoke execute on function public.fn_configurar_pre_go_live_canal(uuid, uuid, text, text[])
  from public, anon, authenticated;
grant execute on function public.fn_configurar_pre_go_live_canal(uuid, uuid, text, text[])
  to service_role;

notify pgrst, 'reload schema';

-- ---- mover em lote sem colidir posiÃ§Ã£o (migration 0209) ----
--
-- A barra de aÃ§Ãµes em lote mandava UM `position_in_stage` para o lote inteiro, e
-- o handler o gravava em N linhas: trinta cards movidos terminavam com o MESMO
-- nÃºmero na etapa de destino. `midpoint(prev, next)` devolve NaN quando os dois
-- vizinhos sÃ£o iguais (`lib/kanban/fractional-indexing.ts`) â€” entÃ£o o primeiro
-- arrasto para ENTRE dois cards do lote mandava NaN como posiÃ§Ã£o, e antes disso
-- a ordem entre eles jÃ¡ era indefinida.
--
-- Esta funÃ§Ã£o dÃ¡ a cada card do lote uma posiÃ§Ã£o DISTINTA (piso da etapa de
-- destino + 1000 por card, na ordem em que estavam no quadro) num Ãºnico
-- `update` â€” o que tambÃ©m torna o lote atÃ´mico: move todos ou nenhum.
--
-- `security INVOKER`: a RLS de crm_leads Ã© o piso. `p_organization_id` Ã© o
-- escopo explÃ­cito que a doutrina exige (org do cookie, nunca do body).
-- Idempotente: `create or replace`, nenhuma coluna, nenhum dado da instalaÃ§Ã£o
-- tocado.

drop function if exists public.fn_mover_leads_em_lote(uuid, uuid[], uuid);

create or replace function public.fn_mover_leads_em_lote(
  p_organization_id uuid,
  p_lead_ids uuid[],
  p_stage_id uuid,
  p_lost_reason text default null
) returns table (lead_id uuid, from_stage_id uuid, pipeline_id uuid)
language plpgsql
set search_path = public
as $$
declare
  v_piso numeric;
  -- Motivo em branco Ã© ausÃªncia de motivo, nunca um motivo de uma letra.
  v_motivo text := nullif(btrim(coalesce(p_lost_reason, '')), '');
  v_coluna_motivo text := '';
begin
  -- `coalesce(..., 0)` cobre a etapa vazia; o DEFAULT da coluna Ã© 1000, entÃ£o
  -- o primeiro card de um lote para uma etapa vazia cai em 1000, como um card
  -- criado Ã  mÃ£o.
  select coalesce(max(l.position_in_stage), 0)
    into v_piso
    from public.crm_leads l
   where l.organization_id = p_organization_id
     and l.stage_id = p_stage_id
     and not (l.id = any(p_lead_ids));

  -- SÃ³ com motivo a gravar a coluna entra na escrita (ver o cabeÃ§alho).
  if v_motivo is not null then
    v_coluna_motivo := ', lost_reason = $4';
  end if;

  return query execute format($f$
  with alvo as (
    select l.id,
           l.stage_id    as from_stage_id,
           l.pipeline_id as pipeline_id,
           -- A ordem do lote no destino Ã© a ordem em que ele estava no quadro:
           -- etapa, depois posiÃ§Ã£o. `id` sÃ³ desempata para o resultado ser
           -- determinÃ­stico (dois cards podem legitimamente empatar hoje â€”
           -- Ã© justamente o estado que a migration 0209 deixa de produzir).
           row_number() over (order by l.stage_id, l.position_in_stage, l.id) as ordem
      from public.crm_leads l
     where l.organization_id = $1
       and l.id = any($2)
  ),
  movidos as (
    update public.crm_leads l
       set stage_id          = $3,
           position_in_stage = $5 + (a.ordem * 1000),
           updated_at        = now()%s
      from alvo a
     where l.id = a.id
       and l.organization_id = $1
    returning l.id, a.from_stage_id, a.pipeline_id
  )
  select m.id, m.from_stage_id, m.pipeline_id from movidos m
  $f$, v_coluna_motivo)
  using p_organization_id, p_lead_ids, p_stage_id, v_motivo, v_piso;
end;
$$;

comment on function public.fn_mover_leads_em_lote(uuid, uuid[], uuid, text) is
  'Move um lote de leads para uma etapa dando a cada um posiÃ§Ã£o DISTINTA (piso da etapa de destino + 1000 por card, na ordem em que estavam no quadro). Existe porque gravar a mesma position_in_stage em N linhas quebra o midpoint() do arrasto seguinte (prev === next â†’ NaN) e deixa a ordem do quadro indefinida. `p_lost_reason` (0263, issue #917) grava o motivo da perda na MESMA escrita quando a etapa de destino Ã© de perda â€” sem ele a CHECK crm_leads_lost_reason_required recusava o lote inteiro com 23514; a coluna sÃ³ entra na escrita quando hÃ¡ motivo, para nÃ£o revalidar o valor que jÃ¡ estava na linha. Devolve uma linha por card movido, com a etapa de ORIGEM, para o handler emitir a atividade de timeline de cada um.';

revoke all     on function public.fn_mover_leads_em_lote(uuid, uuid[], uuid, text) from public;
revoke execute on function public.fn_mover_leads_em_lote(uuid, uuid[], uuid, text) from anon;
grant  execute on function public.fn_mover_leads_em_lote(uuid, uuid[], uuid, text)
  to authenticated, service_role;
