-- ---- O modo de acesso da IA volta atrÃ¡s junto com o gate (migration 0251) ----
-- 0241 Â· Forward-fix da 0218 (issue #602). A RPC gravava o LITERAL
-- 'pre_go_live' em `ai_gate_mode` em toda chamada â€” abrir o canal ao pÃºblico
-- limpava o `ai_gate` e deixava o marcador de teste para trÃ¡s. Ficava inerte
-- enquanto o canal estava aberto e virava armadilha na volta: o script CLI
-- (`scripts/ativar-gate-elegibilidade-ia.ts`, allowlist POR ORIGEM) escrevia sÃ³
-- `{ai_gate}`, e o canal reaparecia em prÃ©-go-live com a lista de testadores
-- velha â€” enquanto o preflight do mesmo script prometia `autorizado` e o motor
-- executava `fora_da_lista_de_teste`. Aqui `ai_gate_mode` recebe o modo REAL
-- (`p_modo`), no vocabulÃ¡rio do contrato da tela ('open' | 'pre_go_live').
-- `create or replace`, sem DDL novo e sem backfill: o estado antigo Ã© inerte e
-- sai na prÃ³xima gravaÃ§Ã£o da tela ou do script.

create or replace function public.fn_configurar_pre_go_live_canal(
  p_org uuid,
  p_canal uuid,
  p_modo text,
  p_numeros text[]
)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_linhas integer;
  v_gate text;
begin
  if p_modo is null or p_modo not in ('open', 'pre_go_live') then
    raise exception 'modo de acesso da IA invÃ¡lido' using errcode = '22023';
  end if;

  if p_numeros is null or exists (
    select 1
      from unnest(p_numeros) as n(numero)
     where numero is null or numero !~ '^\+[1-9][0-9]{7,14}$'
  ) then
    raise exception 'lista de telefones de teste invÃ¡lida' using errcode = '22023';
  end if;

  v_gate := case when p_modo = 'pre_go_live' then 'allowlist' else 'open' end;

  update public.channel_sessions
     set metadata = jsonb_set(
       jsonb_set(
         jsonb_set(coalesce(metadata, '{}'::jsonb), '{ai_gate}', to_jsonb(v_gate), true),
         -- O modo REAL, nÃ£o o literal (o defeito da issue #602).
         '{ai_gate_mode}', to_jsonb(p_modo), true
       ),
       '{ai_test_phone_numbers}', to_jsonb(p_numeros), true
     )
   where organization_id = p_org
     and id = p_canal
     and archived_at is null;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$$;

