-- ---- lead do ingest nao duplica (migration 0256) ----
-- Check-then-act em TypeScript deixava trÃªs mensagens seguidas virarem trÃªs
-- negÃ³cios (medido: mesmo contato, trÃªs cards Ã s 17:07). O advisory lock
-- serializa sÃ³ o MESMO contato; um Ã­ndice Ãºnico resolveria a corrida e
-- quebraria o caso legÃ­timo de dois negÃ³cios abertos criados Ã  mÃ£o.
create or replace function public.fn_nascer_lead_da_conversa(
  p_org uuid,
  p_contact uuid,
  p_pipeline uuid,
  p_stage uuid,
  p_title text,
  p_source text,
  p_source_metadata jsonb default '{}'::jsonb,
  p_tags text[] default '{}'::text[]
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
begin
  -- Serializa por (organizaÃ§Ã£o, contato). Transaction-scoped: liberado no
  -- commit, sem risco de lock vazado.
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || p_contact::text, 0));

  select id into v_id
    from public.crm_leads
   where organization_id = p_org
     and contact_id = p_contact
     and status = 'open'
   limit 1;

  -- NULL significa "jÃ¡ existe", e quem chama traduz isso para `ja_existe`. NÃ£o Ã©
  -- erro: Ã© o desfecho correto da segunda mensagem.
  if v_id is not null then
    return null;
  end if;

  insert into public.crm_leads
    (organization_id, pipeline_id, stage_id, contact_id, title, source, source_metadata, tags)
  values
    (p_org, p_pipeline, p_stage, p_contact, p_title, p_source, coalesce(p_source_metadata, '{}'::jsonb), coalesce(p_tags, '{}'::text[]))
  returning id into v_id;

  return v_id;
end;
$$;

