$$;
revoke all     on function public.fn_registrar_jid_do_aviso(uuid,text) from public, anon, authenticated;
grant  execute on function public.fn_registrar_jid_do_aviso(uuid,text) to service_role;

-- â”€â”€ O contador do descarte â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- Chamada pelos ingestores quando uma mensagem do nÃºmero interno Ã© descartada.
-- Sem ela o silÃªncio Ã© indistinguÃ­vel de defeito para quem olha a tela.
create or replace function public.fn_contar_mensagem_ignorada(p_org uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if p_org is null then
    return;
  end if;
  -- `updated_at` FICA FORA, de propÃ³sito: uma resposta do suporte nÃ£o Ã© alguÃ©m
  -- mexendo na configuraÃ§Ã£o, e a tela usa aquele carimbo para dizer "alterado
  -- por Fulano em tal dia".
  update public.config_aviso_de_caso
     set mensagens_ignoradas = mensagens_ignoradas + 1,
