    ref_id = null
  where organization_id = p_organization_id
    -- `aviso_de_caso_nao_entregue` (migration 0292) entra AQUI e nÃ£o num
    -- passo prÃ³prio: Ã© o mesmo predicado polimÃ³rfico, e o braÃ§o
