revoke all on public.campaign_channel_sessions from anon, authenticated;
grant select on public.campaign_channel_sessions to authenticated;
grant all on public.campaign_channel_sessions to service_role;


-- ---- campanha declara funil, etapa e agente (migration 0378) ----
-- 0378 â€” A CAMPANHA DECLARA FUNIL, ETAPA E AGENTE
--
-- TrÃªs colunas nullable em `campaigns`, e o Ã­ndice que o degrau novo do
-- roteamento precisa. Aditiva: campanha que jÃ¡ existe continua com tudo NULL e
-- se comporta exatamente como antes.
--
-- â•â•â• `pipeline_id` / `stage_id` â€” onde o card nasce â•â•â•
--
-- Hoje quem decide o funil de um lead nascido de conversa Ã© o NÃšMERO
-- (`crm_pipelines.channel_session_id`, migration 0262), com o funil padrÃ£o sem
-- nÃºmero como reserva. A campanha passa a poder dizer o funil e a etapa, e
-- VENCE o nÃºmero quando declara â€” decisÃ£o do dono (2026-09-19): quem montou a
-- campanha sabe o que quer medir, e Ã© a escolha mais especÃ­fica. Quem nÃ£o
-- declarar continua caindo na regra da 0262, sem mudanÃ§a nenhuma.
--
-- â•â•â• `agent_id` â€” quem atende quem responde â•â•â•
--
-- A dÃ­vida estava DECLARADA no repo desde antes desta entrega, em
-- `lib/ai/elegibilidade/campanha.ts`: "encaminhar por campanha exige levar o
-- agent_id (â€¦) e o resolve-turn-agent respeitÃ¡-lo â€” nÃ£o feito nesta entrega".
-- O schema de lÃ¡ jÃ¡ aceitava `agent_id` e o ignorava.
--
-- Hoje quem atende a resposta de uma campanha Ã© o agente publicado no NÃšMERO,
-- ou o roteador dele. Para prospecÃ§Ã£o isso Ã© errado por construÃ§Ã£o: o roteiro
-- de quem aborda Ã© outro, e a LIA-2026-01 promete que quem perguntar "de onde
-- veio meu contato?" recebe a resposta na hora â€” promessa que sÃ³ se cumpre se
-- QUEM ATENDE souber respondÃª-la.
--
-- O agente da campanha sÃ³ assume conversa que NASCE dela (decisÃ£o do dono): o
-- cliente antigo que responde a uma reativaÃ§Ã£o continua com quem jÃ¡ o atendia,
-- em vez de ser sequestrado para o roteiro de prospecÃ§Ã£o.

alter table public.campaigns add column if not exists pipeline_id uuid;
alter table public.campaigns add column if not exists stage_id uuid;
alter table public.campaigns add column if not exists agent_id uuid;

-- Alvos das FKs compostas: Ã­ndice Ãºnico (organization_id, id) em cada tabela.
-- Mesmo cuidado da 0262 â€” criar sÃ³ se NÃƒO houver Ã­ndice Ãºnico sobre exatamente
-- essas duas colunas, senÃ£o toda instalaÃ§Ã£o ganha um segundo Ã­ndice idÃªntico,
-- pago em cada escrita.
do $$
declare
  alvo text;
begin
  foreach alvo in array array['crm_pipelines', 'crm_stages', 'ai_agents'] loop
    if not exists (
      select 1
        from pg_index i
        join pg_class t on t.oid = i.indrelid
       where t.relname = alvo
         and t.relnamespace = 'public'::regnamespace
         and i.indisunique
         and i.indnatts = 2
         and (
           select array_agg(a.attname::text order by k.ord)
             from unnest(i.indkey) with ordinality as k(attnum, ord)
             join pg_attribute a on a.attrelid = t.oid and a.attnum = k.attnum
         ) = array['organization_id', 'id']
    ) then
      execute format('create unique index uq_%s_org_id on public.%I (organization_id, id)', alvo, alvo);
    end if;
  end loop;
end $$;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'campaigns_pipeline_org_fk') then
    alter table public.campaigns
      add constraint campaigns_pipeline_org_fk
      foreign key (organization_id, pipeline_id)
      references public.crm_pipelines (organization_id, id)
      on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'campaigns_stage_org_fk') then
    alter table public.campaigns
      add constraint campaigns_stage_org_fk
      foreign key (organization_id, stage_id)
      references public.crm_stages (organization_id, id)
      on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'campaigns_agent_org_fk') then
    alter table public.campaigns
      add constraint campaigns_agent_org_fk
      foreign key (organization_id, agent_id)
      references public.ai_agents (organization_id, id)
      on delete set null;
  end if;
end $$;

-- Etapa sem funil seria um card sem coluna: o par anda junto ou nÃ£o anda.
do $$
begin
