-- ---- o aviso da Central anuncia no barramento que nasceu (migration 0442) ----
--
-- Ver o cabeÃ§alho da migration: trigger AFTER INSERT em `agent_inbox_items`
-- emite `central.aviso_criado` (item, kind, ref) para o push decidir o que vai
-- ao celular. Sem I/O; falha do anÃºncio nÃ£o impede o aviso de nascer; aviso de
-- plataforma (organizaÃ§Ã£o nula) nÃ£o anuncia. FunÃ§Ã£o com as DUAS origens de
-- EXECUTE revogadas. Entra ANTES da VARREDURA anon porque cria funÃ§Ã£o.
-- Idempotente (`create or replace` + `drop trigger if exists`).
create or replace function public.fn_emit_aviso_da_central()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Aviso de PLATAFORMA (organizaÃ§Ã£o nula) nÃ£o vai para o celular de ninguÃ©m.
  if new.organization_id is null then
    return null;
  end if;
  begin
    perform public.emit_event(
      'central.aviso_criado',
      'agent_inbox_item',
      new.id,
      jsonb_build_object(
        'item_id',  new.id,
        'kind',     new.kind,
        'ref_kind', new.ref_kind,
        'ref_id',   new.ref_id
      ),
      '{}'::jsonb,
      new.organization_id   -- SEMPRE de `new`: Ã© o filtro de tenant
    );
  exception when others then
    raise warning 'fn_emit_aviso_da_central: anÃºncio do aviso % falhou: %', new.id, sqlerrm;
  end;
  return null;              -- AFTER trigger: o retorno Ã© ignorado
end;
$$;

alter function public.fn_emit_aviso_da_central() owner to postgres;

-- As DUAS origens de EXECUTE (doutrina de migrations, item 9). FunÃ§Ã£o de
-- trigger: ninguÃ©m a chama pela REST, entÃ£o nÃ£o hÃ¡ `grant` a ninguÃ©m.
revoke all     on function public.fn_emit_aviso_da_central() from public;
revoke execute on function public.fn_emit_aviso_da_central() from anon, authenticated;

drop trigger if exists trg_aviso_da_central_criado on public.agent_inbox_items;
create trigger trg_aviso_da_central_criado
  after insert on public.agent_inbox_items
  for each row execute function public.fn_emit_aviso_da_central();

