  before update on public.channel_session_groups
  for each row execute function public.fn_set_updated_at();

-- 3. Roteamento automÃ¡tico nÃ£o atribui grupo (quebraria a visibilidade por "sem dono").
create or replace function public.fn_request_channel_routing(p_org uuid,p_conversation uuid)
returns void language plpgsql security definer set search_path=public as $$
declare c public.conversations;
begin
 select * into c from public.conversations where organization_id=p_org and id=p_conversation;
 if not found or c.assigned_to_user_id is not null or c.status not in('open','pending','claimed','ai_handling') then return;end if;
 if c.is_group then return; end if; -- grupos: nunca roteados (migration 0482)
 insert into public.event_log(organization_id,event_type,entity_kind,entity_id,payload)
 values(p_org,'conversation.routing_requested','conversation',c.id,
  jsonb_build_object('organization_id',p_org,'conversation_id',c.id,'channel_session_id',c.channel_session_id))
 on conflict(organization_id,entity_id) where event_type='conversation.routing_requested' and status in('pending','processing')
 do update set next_attempt_at=case when event_log.status='pending' then now() else event_log.next_attempt_at end;
end;
$$;
revoke all on function public.fn_request_channel_routing(uuid,uuid) from public,anon,authenticated;
grant execute on function public.fn_request_channel_routing(uuid,uuid) to service_role;

-- 4. Mensagem recebida em grupo emite message.group_received: nenhum consumidor de
-- message.received (IA, follow-up, campanhas, automaÃ§Ãµes, webhooks, sentimento) a vÃª.
create or replace function public.fn_emit_message_event() returns trigger
language plpgsql set search_path to 'public', 'pg_temp' as $$
declare
  v_event text;
begin
  if new.direction = 'inbound' then
    if exists (select 1 from public.conversations c
               where c.id = new.conversation_id and c.organization_id = new.organization_id and c.is_group) then
      v_event := 'message.group_received';
    else
      v_event := 'message.received';
    end if;
  else
    v_event := case new.status
                 when 'sending' then 'message.sending'
                 when 'sent' then 'message.sent'
                 when 'failed' then 'message.failed'
                 else 'message.outbound'
               end;
  end if;

  perform public.fn_log_event(
    new.organization_id, v_event,
    jsonb_build_object(
      'message_id', new.id, 'conversation_id', new.conversation_id,
      'contact_id', new.contact_id, 'direction', new.direction,
      'type', new.type, 'status', new.status, 'external_id', new.external_id,
      'channel_session_id', new.channel_session_id,
      'body_preview', "left"(new.body, 280)
    )
  );
  return new;
end$$;
grant all on function public.fn_emit_message_event() to anon;
grant all on function public.fn_emit_message_event() to authenticated;
grant all on function public.fn_emit_message_event() to service_role;

-- 5. Cascata de anonimizaÃ§Ã£o LGPD alcanÃ§a channel_session_groups.subject.
-- O corpo Ã© o da 0477 (redact alcanÃ§a crm_proposals) INTEIRO, mais um passo:
-- o de channel_session_groups, antes da linha de auditoria. Esta migration vem
-- DEPOIS da 0477 na cadeia de propÃ³sito: `create or replace` reescreve o corpo
-- inteiro, e partir de um corpo anterior tiraria as propostas (o PDF no bucket
-- `propostas` e as colunas redigidas) da anonimizaÃ§Ã£o em quem aplica a cadeia.
create or replace function public.fn_lgpd_cascade_redact_contact(p_organization_id uuid, p_contact_id uuid, p_request_id uuid) returns jsonb
    language plpgsql security definer
    set search_path to 'public', 'extensions', 'pg_temp'
    as $$
declare
  v_already bool;
  v_counts jsonb := '{}'::jsonb;
  v_media_paths text[] := '{}';
  v_anon_label text;
  v_count int;
  v_variantes text[] := '{}';
begin
  perform public.fn_service_lock(p_organization_id,p_contact_id);
  select is_anonymized into v_already
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  if not found then
    raise exception 'contact not found' using errcode = 'P0002';
  end if;

  if v_already then
    return jsonb_build_object('already_anonymized', true, 'counts', v_counts, 'media_paths', v_media_paths);
  end if;

  v_anon_label := 'Cliente Anonimizado #' || substring(p_contact_id::text from 1 for 8);

  select coalesce(public.fn_telefone_variantes(phone_number), '{}')
    into v_variantes
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  select coalesce(array_agg(distinct media_storage_path) filter (where media_storage_path is not null), '{}')
    into v_media_paths
    from messages
    where organization_id = p_organization_id
      and conversation_id in (
        select id from conversations
          where contact_id = p_contact_id and organization_id = p_organization_id
      );

  -- 1. contacts (irreversible)
  update contacts set
    name = v_anon_label,
    display_name = v_anon_label,
    email = null,
    phone_number = null,
    cpf_encrypted = null,
    cpf_hash = null,
    birthdate = null,
    is_anonymized = true,
    anonymized_at = now(),
    consent = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('contacts', v_count);

  -- 2. conversations metadata + preview strip
  update conversations set
    metadata = '{}'::jsonb,
    last_message_preview = null,
    last_handoff_reason = null,
    updated_at = now()
  where contact_id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('conversations', v_count);

  -- 3. messages: redact body + null media + strip metadata (preserve status/timestamps/conversation_id)
  update messages set
    body = '[mensagem anonimizada]',
    media_url = null,
    media_mime = null,
    media_size_bytes = null,
    media_storage_path = null,
    metadata = '{}'::jsonb,
    updated_at = now()
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('messages', v_count);

  -- 4. crm_lead_activities â€” strip payload, metadata E reason (migration 0071).
  update crm_lead_activities set
    payload = '{}'::jsonb,
    metadata = '{}'::jsonb,
    reason = null
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or lead_id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
      or lead_id in (
        select id from crm_leads
          where contact_id = p_contact_id and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('activities', v_count);

  -- 5. crm_leads â€” strip title/description/custom_fields/source_metadata/tags but PRESERVE pipeline/stage/value
  update crm_leads set
    title = v_anon_label,
    description = null,
    custom_fields = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('leads', v_count);

  -- 6. orders â€” PRESERVE values + status + timestamps. Strip personal fields from payload jsonb
  --    and replace customer_external_id with null (FK-safe; soft de-link). Keep contact_id null.
  update orders set
    payload = (coalesce(payload, '{}'::jsonb))
      - 'customer'
      - 'customer_name'
      - 'customer_email'
      - 'customer_phone'
      - 'shipping_address'
      - 'billing_address'
      - 'contact_identification',
    customer_external_id = null,
    contact_id = null,
    is_anonymized = true,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('orders', v_count);

  -- 6b. crm_proposals (migration 0477, #1504) â€” PRESERVA nÃºmero, valores,
  -- itens, datas e status; redige sÃ³ o que identifica a PESSOA. Ver o
  -- cabeÃ§alho desta migration para o porquÃª de cada coluna.
  -- O PDF que o cliente recebeu (bucket `propostas`, `<org>/<proposta>.pdf`)
  -- tem o nome dele impresso: redigir as colunas e deixar o arquivo seria
  -- anonimizar a linha e manter o documento. Vai para a mesma fila de expurgo
  -- da mÃ­dia (passo 7), com o bucket CERTO â€” a mensagem que levou o PDF
  -- aponta para o mesmo caminho, mas o passo 7 sÃ³ enfileira `whatsapp-media`.
  -- Lido ANTES de o passo seguinte zerar `pdf_path`.
  insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
  select p_organization_id, p_request_id, 'propostas', pdf_path
    from crm_proposals
   where organization_id = p_organization_id
     and contact_id = p_contact_id
     and pdf_path is not null and length(pdf_path) > 0
     -- sÃ³ arquivo DESTA organizaÃ§Ã£o: o expurgo nunca alcanÃ§a o PDF de outra
     and pdf_path like p_organization_id::text || '/%'
  on conflict (bucket, object_path) do nothing;
  update crm_proposals set
    destinatario_nome = v_anon_label,
    briefing_json = '{}'::jsonb,
    resumo_comercial = null,
    -- o texto do documento como foi montado e como foi editado Ã  mÃ£o: Ã© o
    -- conteÃºdo do PDF, com o mesmo nome dentro.
    rendered_snapshot = null,
    secoes_editadas = null,
    pdf_path = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('crm_proposals', v_count);

  -- CAMPANHAS: o que foi DITO Ã  pessoa e o endereÃ§o para onde foi.
  update campaign_recipients set
    rendered_body = null,
    recipient_address = null,
    variables = '{}'::jsonb,
    last_error_detail = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('campaign_recipients', v_count);

  -- LISTA DE EXCLUSÃƒO: solta o vÃ­nculo e apaga a cauda do telefone.
  update campaign_suppressions set
    address_tail = null,
    reason = null,
    contact_id = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('campaign_suppressions', v_count);

  -- 6c. sales â€” a comanda. PRESERVA valor, status e datas, e NÃƒO desliga o
  --     contato (ver racional completo no baseline, bloco desta funÃ§Ã£o).
  update sales set
    notes = null,
    cancel_reason = case when cancel_reason is null then null else '[redigido]' end,
    reverse_reason = case when reverse_reason is null then null else '[redigido]' end,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('sales', v_count);

  -- 7. enqueue media for async deletion (idempotent via unique (bucket, object_path))
  if array_length(v_media_paths, 1) > 0 then
    insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
    select p_organization_id, p_request_id, 'whatsapp-media', path
      from unnest(v_media_paths) as path
      where path is not null and length(path) > 0
    on conflict (bucket, object_path) do nothing;
  end if;

  -- 7b. voice_calls â€” o TELEFONE de quem falou ao telefone (migration 0235).
  update voice_calls set
    peer_phone = v_anon_label,
    owner_user_id = null,
    created_by = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('voice_calls', v_count);

  update prospecting_candidates set suppression_salt = gen_random_bytes(32)
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)))
    and suppression_salt is null;
  update prospecting_candidates set
    suppression_place = hmac(convert_to(place_id, 'UTF8'), suppression_salt, 'sha256'),
    suppression_phone = case when phone is null then null
      else hmac(convert_to(phone, 'UTF8'), suppression_salt, 'sha256') end,
    place_id = 'redacted:' || id::text,
    phone = null,
    data = jsonb_build_object('key', 'redacted:' || id::text,
      'name', v_anon_label, 'phone', null, 'website', null,
      'category', null, 'address', null, 'maps_url', null,
      'rating', null, 'reviews', null, 'emails', '[]'::jsonb, 'socials', '[]'::jsonb),
    status = 'skipped', service_boundary = null, error = null, updated_at = now()
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)));
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('prospecting_candidates', v_count);

  -- agent_cases â€” o que a IA escreveu SOBRE a pessoa quando travou (migration 0280).
  update agent_cases set
    title = v_anon_label,
    summary = '[resumo anonimizado]',
    blocker = '[bloqueio anonimizado]',
    context_snapshot = '{}'::jsonb
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_cases', v_count);

  -- agent_case_events â€” a linha do tempo do caso (migration 0280).
  update agent_case_events set
    body = null,
    metadata = '{}'::jsonb
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_events', v_count);

  -- demandas â€” o assunto do pedido (migration 0280).
  update demandas set
    assunto = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('demandas', v_count);

  -- agent_inbox_items â€” o aviso que leva o texto do caso para a Central (migration 0280/0292).
  update agent_inbox_items set
    status = 'resolved',
    resolved_at = now(),
    body = 'Contato anonimizado.',
    ref_id = null
  where organization_id = p_organization_id
    and kind in ('handoff', 'case_stale', 'aviso_de_caso_nao_entregue')
    and (
      (ref_kind = 'contact' and ref_id = p_contact_id)
      or (ref_kind = 'conversation' and ref_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          ))
      or (ref_kind = 'agent_case' and ref_id in (
            select id from agent_cases
              where organization_id = p_organization_id
                and conversation_id in (
                  select id from conversations
                    where contact_id = p_contact_id and organization_id = p_organization_id
                )
          ))
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_inbox_items', v_count);

  -- agent_case_chat_messages â€” a consulta interna da equipe Ã  IA SOBRE o caso (migration 0281).
  update agent_case_chat_messages set
    body = null,
    redacted_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id
    and redacted_at is null;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_chat_messages', v_count);

  -- passagens_de_atendimento â€” o BRIEFING Ã© sobre a pessoa (migration 0291).
  update passagens_de_atendimento set
    body       = v_anon_label,
    title      = null,
    notes      = null,
    content    = null,
    tentativas = '[]'::jsonb
  where organization_id = p_organization_id and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('passagens_de_atendimento', v_count);

  -- entregas_de_aviso_de_caso â€” o registro do aviso ao suporte (migration 0292).
  update entregas_de_aviso_de_caso set
    erro_detalhe = null
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('entregas_de_aviso_de_caso', v_count);

  -- channel_session_groups.subject â€” o NOME do grupo, e a FK contact_id aponta
  -- para o placeholder do grupo (contacts.kind = 'whatsapp_group'), nunca para
  -- o titular real sendo anonimizado neste caminho â€” mas a FK para contacts e o
  -- nome da coluna casam o padrÃ£o automÃ¡tico do escopo (migration 0482), e
  -- nulificar nÃ£o perde nada operacional: nÃºmero, conversa e liga/desliga ficam.
  update public.channel_session_groups set
    subject = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('channel_session_groups', v_count);

  -- 8. dense audit row
  insert into api_audit_log (organization_id, action, actor_user_id, resource_type, resource_id, metadata, bypassed_rls)
  values (
    p_organization_id,
    'lgpd.redact_executed',
    null,
    'contact',
    p_contact_id,
    jsonb_build_object(
      'cascaded_to', v_counts,
      'media_queued', coalesce(array_length(v_media_paths, 1), 0),
      'request_id', p_request_id
    ),
    true
  );

  return jsonb_build_object(
    'already_anonymized', false,
    'counts', v_counts,
    'media_paths', v_media_paths
  );
end;
$$;

revoke all on function public.fn_lgpd_cascade_redact_contact(uuid,uuid,uuid) from public, anon, authenticated;
grant execute on function public.fn_lgpd_cascade_redact_contact(uuid,uuid,uuid) to service_role;

-- 6. Grupo sem dono Ã© conversa HUMANA esperando alguÃ©m ('aguardando'), nunca
-- 'automatico': o automÃ¡tico nunca atende grupo (o banco nem emite
-- message.received para ele). Sem isto o grupo aparecia como "AutomÃ¡tico
-- atendendo" e morava na aba AutomÃ¡tico, fora da fila humana.
-- `p_is_group` entra como SÃ‰TIMO parÃ¢metro, com default: a assinatura de seis Ã©
-- removida antes (duas sobrecargas com default tornariam a chamada de seis
-- ambÃ­gua). FunÃ§Ãµes `language sql` nÃ£o registram dependÃªncia, entÃ£o o drop nÃ£o
-- arrasta `comando_da_conversa(c)`, que Ã© recriada logo abaixo passando
-- `c.is_group`. Espelho TS: `comandoDaConversa()` em
-- lib/inbox/comando-da-conversa.ts, casados por
-- tests/invariants/comando-da-conversa-espelha-o-ts.test.ts.
drop function if exists public.fn_comando_da_conversa(text, uuid, timestamptz, boolean, boolean, timestamptz);
create or replace function public.fn_comando_da_conversa(
  p_status                text,
  p_assigned_to_user_id   uuid,
  p_bot_silenced_until    timestamptz,
  p_force_human           boolean,
  p_is_blocked            boolean,
  p_agora                 timestamptz,
  p_is_group              boolean default false
) returns text
language sql
immutable
set search_path = public
as $fn_comando$
  select case
    -- A ordem Ã© a mesma de `comandoDaConversa`, e ela Ã© o contrato: dono primeiro
    -- (a aba "Fechadas" precisa continuar dizendo QUEM atendeu), encerrada depois,
    -- e sÃ³ entÃ£o as travas â€” grupo entre elas.
    when p_assigned_to_user_id is not null then 'humano'
    when p_status in ('closed', 'archived', 'resolved') then 'encerrada'
    when p_is_group is true
      or p_force_human is true
      or p_is_blocked is true
      or (p_bot_silenced_until is not null and p_bot_silenced_until > p_agora) then 'aguardando'
    else 'automatico'
  end;
$fn_comando$;

comment on function public.fn_comando_da_conversa(text, uuid, timestamptz, boolean, boolean, timestamptz, boolean)
  is 'Quem manda na conversa. Espelho SQL de comandoDaConversa() (lib/inbox/comando-da-conversa.ts); as duas sÃ£o casadas por tests/invariants/comando-da-conversa-espelha-o-ts.test.ts. Grupo sem dono Ã© aguardando (migration 0482).';

-- `comando_da_conversa` segue a forma da 0404 (issue #1571, upstream):
-- SECURITY DEFINER para a contagem das abas nÃ£o reavaliar a RLS de `contacts`
-- por conversa, parÃ¢metro SEM NOME para a PostgREST nÃ£o publicÃ¡-la em `/rpc`, e
-- as subconsultas presas a `ct.organization_id = $1.organization_id`. O que esta
-- migration acrescenta Ã© sÃ³ o sÃ©timo argumento, `$1.is_group`. Este bloco vem
-- DEPOIS do da 0404 de propÃ³sito: Ã© a Ãºltima definiÃ§Ã£o que vale, e ela tem de
-- carregar as duas decisÃµes. DROP sem `cascade`, como na 0404 (nada depende
-- dela); o DROP leva a ACL, entÃ£o as duas origens de EXECUTE voltam explÃ­citas.
drop function if exists public.comando_da_conversa(public.conversations);

create function public.comando_da_conversa(public.conversations)
returns text
language sql
stable
security definer
set search_path = public
as $comando$
  select public.fn_comando_da_conversa(
    $1.status,
    $1.assigned_to_user_id,
    $1.bot_silenced_until,
    coalesce((select ct.force_human from public.contacts ct where ct.id = $1.contact_id and ct.organization_id = $1.organization_id), false),
    coalesce((select ct.is_blocked  from public.contacts ct where ct.id = $1.contact_id and ct.organization_id = $1.organization_id), false),
    now(),
    coalesce($1.is_group, false)
  );
$comando$;

comment on function public.comando_da_conversa(public.conversations)
  is 'Campo calculado exposto pelo PostgREST: ?select=comando_da_conversa e ?comando_da_conversa=in.(...). Resolve o contato e carimba now(); a regra em si Ã© fn_comando_da_conversa. SECURITY DEFINER desde a 0404 (issue #1571: a contagem das abas reavaliava a RLS de contacts 2x por conversa); parÃ¢metro SEM NOME de propÃ³sito â€” com nome a PostgREST a exporia em /rpc, e ali uma linha fabricada leria force_human/is_blocked de outro tenant. Passa is_group desde a 0482 (grupos de WhatsApp na inbox).';

revoke execute on function public.fn_comando_da_conversa(text, uuid, timestamptz, boolean, boolean, timestamptz, boolean) from public, anon;
revoke execute on function public.comando_da_conversa(public.conversations) from public, anon;
grant  execute on function public.fn_comando_da_conversa(text, uuid, timestamptz, boolean, boolean, timestamptz, boolean) to authenticated, service_role;
grant  execute on function public.comando_da_conversa(public.conversations) to authenticated, service_role;

-- 7. LGPD alcanÃ§a as mensagens de GRUPO escritas por quem JÃ Ã‰ contato do CRM.
--
-- A mensagem de grupo mora na conversa do contato PLACEHOLDER do grupo, nÃ£o na
-- do titular: o autor sÃ³ existe em `messages.metadata.group_sender`
-- ({name, phone, lid}). Sem este passo, anonimizar alguÃ©m deixava tudo o que
-- ele escreveu nos grupos ligados â€” corpo, mÃ­dia e o prÃ³prio rÃ³tulo com nome e
-- telefone â€” intacto.
--
-- O passo mora no GATILHO da virada de `is_anonymized` (migration 0391), e nÃ£o
-- em `fn_lgpd_cascade_redact_contact`, pela mesma razÃ£o que trouxe o gatilho:
-- os DOIS caminhos (o pedido formal e o botÃ£o da ficha) passam por ele. O
-- casamento Ã© pelo telefone (`fn_telefone_variantes`, com e sem o nono dÃ­gito)
-- OU pelo lid (`contacts.wa_lid`), lidos de OLD: os dois caminhos zeram
-- `phone_number` no MESMO update que vira `is_anonymized`, e a cascata formal
-- zera tambÃ©m `source_metadata`, de onde o lid Ã© GERADO. Ler de NEW nÃ£o
-- alcanÃ§aria linha nenhuma â€” e pareceria feito.
--
-- âš ï¸ SÃ³ alcanÃ§a quem JÃ Ã‰ contato do CRM. O participante de grupo que nunca
-- virou contato nÃ£o tem ficha, nÃ£o tem pedido LGPD e nÃ£o tem caminho por aqui:
-- achÃ¡-lo exigiria buscar por telefone/lid solto, fora de um titular â€” mudanÃ§a
-- de desenho, nÃ£o esquecimento. Ver a spec, "LGPD â€” mensagens de grupo".
--
-- Sem cura retroativa, de propÃ³sito: mensagem de grupo sÃ³ existe a partir desta
-- migration, e o gatilho nasce junto com ela.
--
-- ponytail: varredura sem Ã­ndice sobre as mensagens de grupo da org; um Ã­ndice
-- de expressÃ£o em (metadata->'group_sender'->>'phone') resolve se anonimizar
-- ficar lento em org com muito grupo.
create or replace function public.fn_redigir_conversas_ao_anonimizar()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_variantes text[];
  v_lid text;
  v_msgs_de_grupo uuid[];
begin
  insert into public.storage_redaction_queue (organization_id, bucket, object_path)
  select distinct new.organization_id, 'whatsapp-media', m.media_storage_path
    from public.messages m
   where m.organization_id = new.organization_id
     and m.conversation_id in (
       select c.id from public.conversations c
        where c.contact_id = new.id and c.organization_id = new.organization_id)
     and m.media_storage_path is not null
     and length(m.media_storage_path) > 0
  on conflict (bucket, object_path) do nothing;

  update public.messages set
    body = '[mensagem anonimizada]',
    media_url = null,
    media_mime = null,
    media_size_bytes = null,
    media_storage_path = null,
    metadata = '{}'::jsonb,
    updated_at = now()
  where organization_id = new.organization_id
    and conversation_id in (
      select c.id from public.conversations c
       where c.contact_id = new.id and c.organization_id = new.organization_id);

  update public.conversations set
    metadata = '{}'::jsonb,
    last_message_preview = null,
    last_handoff_reason = null,
    updated_at = now()
  where contact_id = new.id and organization_id = new.organization_id;

  update public.lead_checkpoints set
    rolling_summary = '[resumo anonimizado]',
    commitments = '[]'::jsonb,
    objections = '[]'::jsonb,
    next_action = null,
    declaracao = null
  where contact_id = new.id and organization_id = new.organization_id;

  -- Mensagens de grupo escritas pelo titular (ver o cabeÃ§alho deste bloco).
  v_variantes := coalesce(public.fn_telefone_variantes(coalesce(old.phone_number, new.phone_number)), '{}');
  v_lid := coalesce(old.wa_lid, new.wa_lid);

  select coalesce(array_agg(m.id), '{}')
    into v_msgs_de_grupo
    from public.messages m
   where m.organization_id = new.organization_id
     and m.metadata ? 'group_sender'
     and (
       regexp_replace(coalesce(m.metadata->'group_sender'->>'phone', ''), '\D', '', 'g') = any(v_variantes)
       or (v_lid is not null and m.metadata->'group_sender'->>'lid' = v_lid)
     );

  if cardinality(v_msgs_de_grupo) > 0 then
    -- MÃ­dia ANTES de zerar a coluna, pelo mesmo motivo do comeÃ§o da funÃ§Ã£o.
    insert into public.storage_redaction_queue (organization_id, bucket, object_path)
    select distinct new.organization_id, 'whatsapp-media', m.media_storage_path
      from public.messages m
     where m.organization_id = new.organization_id
       and m.id = any(v_msgs_de_grupo)
       and m.media_storage_path is not null
       and length(m.media_storage_path) > 0
    on conflict (bucket, object_path) do nothing;

    -- A prÃ©via da conversa do GRUPO pode ser o texto do titular: sai junto. As
    -- mensagens dos outros participantes ficam; a prÃ³xima que chegar a repÃµe.
    update public.conversations set
      last_message_preview = null,
      updated_at = now()
    where organization_id = new.organization_id
      and id in (select m.conversation_id from public.messages m
                  where m.organization_id = new.organization_id and m.id = any(v_msgs_de_grupo));

    update public.messages set
      body = '[mensagem anonimizada]',
      media_url = null,
      media_mime = null,
      media_size_bytes = null,
      media_storage_path = null,
      metadata = '{}'::jsonb,
      updated_at = now()
    where organization_id = new.organization_id
      and id = any(v_msgs_de_grupo);
  end if;

  return new;
end
$$;

-- As DUAS origens de EXECUTE (item 9 do CLAUDE.md), repetidas: `create or
-- replace` preserva a ACL, mas quem lÃª este bloco nÃ£o precisa confiar nisso.
revoke all on function public.fn_redigir_conversas_ao_anonimizar() from public;
revoke execute on function public.fn_redigir_conversas_ao_anonimizar() from anon;
revoke execute on function public.fn_redigir_conversas_ao_anonimizar() from authenticated;

notify pgrst, 'reload schema';
-- ---- fim grupos de WhatsApp na inbox (migration 0482) ----

-- ---- anexo na nota interna: mÃ­dia prÃ³pria, bucket prÃ³prio e alcance da LGPD (migration 0483) ----
-- F3 da #1863. O corpo da cascata e o do expurgo sÃ£o gerados do MESMO texto da
-- migration 0483 (script), porque `apendice-do-baseline-nao-diverge-da-cadeia`
-- compara os dois artefatos e quem instala pelo kit self-host aplica SÃ“ o
-- baseline. O bloco do expurgo da 0435, acima, foi EDITADO NO LUGAR (mesmo
-- desenho das 0417/0426/0434/0435): dois corpos da mesma funÃ§Ã£o num arquivo sÃ³
-- faria o segundo vencer sem que o primeiro fosse lido por ninguÃ©m.
alter table public.conversation_notes
  add column if not exists media_storage_path text,
  add column if not exists media_mime text,
  add column if not exists media_size_bytes bigint;

comment on column public.conversation_notes.media_storage_path is
  'Caminho do anexo no bucket internal-media ({org}/{conversa}/note-...). Null = nota sÃ³ com texto.';
comment on column public.conversation_notes.media_mime is
  'MIME real do arquivo GRAVADO (o do upload validado), nÃ£o o que o browser declarou.';
comment on column public.conversation_notes.media_size_bytes is
  'Tamanho do arquivo gravado, em bytes â€” Ã© o que o card mostra (formatBytes).';

insert into storage.buckets (id, name, public, file_size_limit)
values ('internal-media', 'internal-media', false, 52428800)
on conflict (id) do update set file_size_limit = excluded.file_size_limit;

-- ---- bucket internal-media: sem policy, como o whatsapp-media da 0055 ----
-- Leitura e escrita sÃ£o do service_role (rota de upload + signed URL da rota
-- de nota); sem policy, `authenticated` nÃ£o alcanÃ§a o Storage API direto.

create or replace function public.fn_lgpd_cascade_redact_contact(p_organization_id uuid, p_contact_id uuid, p_request_id uuid) returns jsonb
    language plpgsql security definer
    set search_path to 'public', 'extensions', 'pg_temp'
    as $$
declare
  v_already bool;
  v_counts jsonb := '{}'::jsonb;
  v_media_paths text[] := '{}';
  v_anon_label text;
  v_count int;
  v_variantes text[] := '{}';
begin
  perform public.fn_service_lock(p_organization_id,p_contact_id);
  select is_anonymized into v_already
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  if not found then
    raise exception 'contact not found' using errcode = 'P0002';
  end if;

  if v_already then
    return jsonb_build_object('already_anonymized', true, 'counts', v_counts, 'media_paths', v_media_paths);
  end if;

  v_anon_label := 'Cliente Anonimizado #' || substring(p_contact_id::text from 1 for 8);

  select coalesce(public.fn_telefone_variantes(phone_number), '{}')
    into v_variantes
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  select coalesce(array_agg(distinct media_storage_path) filter (where media_storage_path is not null), '{}')
    into v_media_paths
    from messages
    where organization_id = p_organization_id
      and conversation_id in (
        select id from conversations
          where contact_id = p_contact_id and organization_id = p_organization_id
      );

  -- 1. contacts (irreversible)
  update contacts set
    name = v_anon_label,
    display_name = v_anon_label,
    email = null,
    phone_number = null,
    cpf_encrypted = null,
    cpf_hash = null,
    birthdate = null,
    is_anonymized = true,
    anonymized_at = now(),
    consent = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('contacts', v_count);

  -- 2. conversations metadata + preview strip
  update conversations set
    metadata = '{}'::jsonb,
    last_message_preview = null,
    last_handoff_reason = null,
    updated_at = now()
  where contact_id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('conversations', v_count);

  -- 3. messages: redact body + null media + strip metadata (preserve status/timestamps/conversation_id)
  update messages set
    body = '[mensagem anonimizada]',
    media_url = null,
    media_mime = null,
    media_size_bytes = null,
    media_storage_path = null,
    metadata = '{}'::jsonb,
    updated_at = now()
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('messages', v_count);

  -- 4. crm_lead_activities â€” strip payload, metadata E reason (migration 0071).
  update crm_lead_activities set
    payload = '{}'::jsonb,
    metadata = '{}'::jsonb,
    reason = null
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or lead_id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
      or lead_id in (
        select id from crm_leads
          where contact_id = p_contact_id and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('activities', v_count);

  -- 5. crm_leads â€” strip title/description/custom_fields/source_metadata/tags but PRESERVE pipeline/stage/value
  update crm_leads set
    title = v_anon_label,
    description = null,
    custom_fields = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('leads', v_count);

  -- 6. orders â€” PRESERVE values + status + timestamps. Strip personal fields from payload jsonb
  --    and replace customer_external_id with null (FK-safe; soft de-link). Keep contact_id null.
  update orders set
    payload = (coalesce(payload, '{}'::jsonb))
      - 'customer'
      - 'customer_name'
      - 'customer_email'
      - 'customer_phone'
      - 'shipping_address'
      - 'billing_address'
      - 'contact_identification',
    customer_external_id = null,
    contact_id = null,
    is_anonymized = true,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('orders', v_count);

  -- 6b. crm_proposals (migration 0477, #1504) â€” PRESERVA nÃºmero, valores,
  -- itens, datas e status; redige sÃ³ o que identifica a PESSOA. Ver o
  -- cabeÃ§alho desta migration para o porquÃª de cada coluna.
  -- O PDF que o cliente recebeu (bucket `propostas`, `<org>/<proposta>.pdf`)
  -- tem o nome dele impresso: redigir as colunas e deixar o arquivo seria
  -- anonimizar a linha e manter o documento. Vai para a mesma fila de expurgo
  -- da mÃ­dia (passo 7), com o bucket CERTO â€” a mensagem que levou o PDF
  -- aponta para o mesmo caminho, mas o passo 7 sÃ³ enfileira `whatsapp-media`.
  -- Lido ANTES de o passo seguinte zerar `pdf_path`.
  insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
  select p_organization_id, p_request_id, 'propostas', pdf_path
    from crm_proposals
   where organization_id = p_organization_id
     and contact_id = p_contact_id
     and pdf_path is not null and length(pdf_path) > 0
     -- sÃ³ arquivo DESTA organizaÃ§Ã£o: o expurgo nunca alcanÃ§a o PDF de outra
     and pdf_path like p_organization_id::text || '/%'
  on conflict (bucket, object_path) do nothing;
  update crm_proposals set
    destinatario_nome = v_anon_label,
    briefing_json = '{}'::jsonb,
    resumo_comercial = null,
    -- o texto do documento como foi montado e como foi editado Ã  mÃ£o: Ã© o
    -- conteÃºdo do PDF, com o mesmo nome dentro.
    rendered_snapshot = null,
    secoes_editadas = null,
    pdf_path = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('crm_proposals', v_count);

  -- CAMPANHAS: o que foi DITO Ã  pessoa e o endereÃ§o para onde foi.
  update campaign_recipients set
    rendered_body = null,
    recipient_address = null,
    variables = '{}'::jsonb,
    last_error_detail = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('campaign_recipients', v_count);

  -- LISTA DE EXCLUSÃƒO: solta o vÃ­nculo e apaga a cauda do telefone.
  update campaign_suppressions set
    address_tail = null,
    reason = null,
    contact_id = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('campaign_suppressions', v_count);

  -- 6c. sales â€” a comanda. PRESERVA valor, status e datas, e NÃƒO desliga o
  --     contato (ver racional completo no baseline, bloco desta funÃ§Ã£o).
  update sales set
    notes = null,
    cancel_reason = case when cancel_reason is null then null else '[redigido]' end,
    reverse_reason = case when reverse_reason is null then null else '[redigido]' end,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('sales', v_count);

  -- 6d. conversation_notes (migration 0483, F3 da #1863) â€” a nota interna Ã©
  -- texto escrito SOBRE a pessoa durante o atendimento, e o anexo dela Ã© mÃ­dia
  -- ancorada na conversa: os dois entram no alcance do titular. A 0477 jÃ¡
  -- mostrou o desenho (arquivo vai para a fila ANTES de a coluna ser zerada).
  -- O bucket Ã© `internal-media`, e nÃ£o o do passo 7: a nota nunca sobe no
  -- `whatsapp-media` (Ã© o bucket do canal do CLIENTE), e enfileirar o caminho
  -- num bucket onde ele nÃ£o estÃ¡ deixaria a remoÃ§Ã£o apontando para o nada â€”
  -- a mesma falha de nÃ£o ter anonimizado, um endereÃ§o mais para a direita.
  -- Por isso os caminhos de nota tambÃ©m NÃƒO entram em `v_media_paths`: essa
  -- lista sÃ³ existe para o passo 7, que enfileira `whatsapp-media`.
  insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
  select p_organization_id, p_request_id, 'internal-media', n.media_storage_path
    from conversation_notes n
   where n.organization_id = p_organization_id
     and n.conversation_id in (
       select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
     )
     and n.media_storage_path is not null and length(n.media_storage_path) > 0
     and n.media_storage_path like p_organization_id::text || '/%'
  on conflict (bucket, object_path) do nothing;
  update conversation_notes set
    body = '[nota interna anonimizada]',
    media_storage_path = null,
    media_mime = null,
    media_size_bytes = null
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
       where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('conversation_notes', v_count);

  -- 7. enqueue media for async deletion (idempotent via unique (bucket, object_path))
  if array_length(v_media_paths, 1) > 0 then
    insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
    select p_organization_id, p_request_id, 'whatsapp-media', path
      from unnest(v_media_paths) as path
      where path is not null and length(path) > 0
    on conflict (bucket, object_path) do nothing;
  end if;

  -- 7b. voice_calls â€” o TELEFONE de quem falou ao telefone (migration 0235).
  update voice_calls set
    peer_phone = v_anon_label,
    owner_user_id = null,
    created_by = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('voice_calls', v_count);

  update prospecting_candidates set suppression_salt = gen_random_bytes(32)
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)))
    and suppression_salt is null;
  update prospecting_candidates set
    suppression_place = hmac(convert_to(place_id, 'UTF8'), suppression_salt, 'sha256'),
    suppression_phone = case when phone is null then null
      else hmac(convert_to(phone, 'UTF8'), suppression_salt, 'sha256') end,
    place_id = 'redacted:' || id::text,
    phone = null,
    data = jsonb_build_object('key', 'redacted:' || id::text,
      'name', v_anon_label, 'phone', null, 'website', null,
      'category', null, 'address', null, 'maps_url', null,
      'rating', null, 'reviews', null, 'emails', '[]'::jsonb, 'socials', '[]'::jsonb),
    status = 'skipped', service_boundary = null, error = null, updated_at = now()
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)));
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('prospecting_candidates', v_count);

  -- agent_cases â€” o que a IA escreveu SOBRE a pessoa quando travou (migration 0280).
  update agent_cases set
    title = v_anon_label,
    summary = '[resumo anonimizado]',
    blocker = '[bloqueio anonimizado]',
    context_snapshot = '{}'::jsonb
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_cases', v_count);

  -- agent_case_events â€” a linha do tempo do caso (migration 0280).
  update agent_case_events set
    body = null,
    metadata = '{}'::jsonb
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_events', v_count);

  -- demandas â€” o assunto do pedido (migration 0280).
  update demandas set
    assunto = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('demandas', v_count);

  -- agent_inbox_items â€” o aviso que leva o texto do caso para a Central (migration 0280/0292).
  update agent_inbox_items set
    status = 'resolved',
    resolved_at = now(),
    body = 'Contato anonimizado.',
    ref_id = null
  where organization_id = p_organization_id
    and kind in ('handoff', 'case_stale', 'aviso_de_caso_nao_entregue')
    and (
      (ref_kind = 'contact' and ref_id = p_contact_id)
      or (ref_kind = 'conversation' and ref_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          ))
      or (ref_kind = 'agent_case' and ref_id in (
            select id from agent_cases
              where organization_id = p_organization_id
                and conversation_id in (
                  select id from conversations
                    where contact_id = p_contact_id and organization_id = p_organization_id
                )
          ))
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_inbox_items', v_count);

  -- agent_case_chat_messages â€” a consulta interna da equipe Ã  IA SOBRE o caso (migration 0281).
  update agent_case_chat_messages set
    body = null,
    redacted_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id
    and redacted_at is null;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_chat_messages', v_count);

  -- passagens_de_atendimento â€” o BRIEFING Ã© sobre a pessoa (migration 0291).
  update passagens_de_atendimento set
    body       = v_anon_label,
    title      = null,
    notes      = null,
    content    = null,
    tentativas = '[]'::jsonb
  where organization_id = p_organization_id and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('passagens_de_atendimento', v_count);

  -- entregas_de_aviso_de_caso â€” o registro do aviso ao suporte (migration 0292).
  update entregas_de_aviso_de_caso set
    erro_detalhe = null
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('entregas_de_aviso_de_caso', v_count);

  -- channel_session_groups.subject â€” o NOME do grupo, e a FK contact_id aponta
  -- para o placeholder do grupo (contacts.kind = 'whatsapp_group'), nunca para
  -- o titular real sendo anonimizado neste caminho â€” mas a FK para contacts e o
  -- nome da coluna casam o padrÃ£o automÃ¡tico do escopo (migration 0482), e
  -- nulificar nÃ£o perde nada operacional: nÃºmero, conversa e liga/desliga ficam.
  update public.channel_session_groups set
    subject = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('channel_session_groups', v_count);

  -- 8. dense audit row
  insert into api_audit_log (organization_id, action, actor_user_id, resource_type, resource_id, metadata, bypassed_rls)
  values (
    p_organization_id,
    'lgpd.redact_executed',
    null,
    'contact',
    p_contact_id,
    jsonb_build_object(
      'cascaded_to', v_counts,
      'media_queued', coalesce(array_length(v_media_paths, 1), 0),
      'request_id', p_request_id
    ),
    true
  );

  return jsonb_build_object(
    'already_anonymized', false,
    'counts', v_counts,
    'media_paths', v_media_paths
  );
end;
$$;

revoke all on function public.fn_lgpd_cascade_redact_contact(uuid,uuid,uuid) from public, anon, authenticated;
grant execute on function public.fn_lgpd_cascade_redact_contact(uuid,uuid,uuid) to service_role;

-- ---- as seÃ§Ãµes de mÃ³dulo que a anonimizaÃ§Ã£o alcanÃ§a (migration 0485) ----
-- âš ï¸ ENTRA ANTES do bloco da VARREDURA anon: cria funÃ§Ã£o. Corpo IDÃŠNTICO ao da migration
-- 0485 (gate `apendice-do-baseline-nao-diverge-da-cadeia` compara o que o Postgres executa).
-- Idempotente: `if not exists`, `create or replace`, `drop trigger if exists`.
-- 0485 â€” A anonimizaÃ§Ã£o de LGPD alcanÃ§a as SEÃ‡Ã•ES DE MÃ“DULO declaradas (D8 da ADR-0002, #1114)
--
-- Lei: `docs/adr/0002-tabelas-de-modulo-num-banco-so.md`, D8:
--   "AnonimizaÃ§Ã£o e retenÃ§Ã£o alcanÃ§am as tabelas do mÃ³dulo por SQL dinÃ¢mico protegido por
--    `to_regclass`: onde o mÃ³dulo nÃ£o estÃ¡ instalado, pulam sem erro. Uma cascata que citasse
--    a tabela pelo nome abortaria a anonimizaÃ§Ã£o inteira em toda instalaÃ§Ã£o sem o mÃ³dulo â€”
--    medido."
--
-- â”€â”€ O que JÃ existe e o que este arquivo acrescenta â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- A cascata `fn_lgpd_cascade_redact_contact` continua sendo a funÃ§Ã£o Ãºnica do NÃšCLEO (0119 â†’
-- 0482), e a exportaÃ§Ã£o jÃ¡ trata o mÃ³dulo ausente: `lib/lgpd/export-collector.ts` engole sÃ³ o
-- 42P01 ("relation does not exist") e LANÃ‡A para todo outro erro, porque seÃ§Ã£o de mÃ³dulo
-- ilegÃ­vel nunca sai como export completo (D8, parte de export, 0480/#1578).
--
-- O que faltava era o mecanismo GENÃ‰RICO da D8: um mÃ³dulo declara as SUAS seÃ§Ãµes UMA vez, e a
-- anonimizaÃ§Ã£o as alcanÃ§a sem que a cascata ganhe um passo novo a cada mÃ³dulo. Sem isto, o
-- prÃ³ximo mÃ³dulo com texto livre sobre a pessoa sÃ³ ficaria alcanÃ§ado se alguÃ©m lembrasse de
-- reescrever uma funÃ§Ã£o de ~400 linhas â€” e o esquecimento, em LGPD, Ã© o modo de falha silencioso
-- (rota devolve SUCESSO, SLA cumprido, linha legÃ­vel).
--
-- â”€â”€ As trÃªs peÃ§as â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- 1. `modulo_secoes_lgpd` â€” o mÃ³dulo declara `(modulo, tabela, ligacao, colunas, colunas_rotulo)`.
--    Escrito sÃ³ pela migration do mÃ³dulo: RLS ligada, zero policy, `anon`/`authenticated` sem
--    privilÃ©gio (mesmo desenho de `modulos_instalados`, 0340). Nenhum mÃ³dulo oficial declara
--    linha hoje â€” honorÃ¡rios nÃ£o tem texto livre sobre a pessoa (decisÃ£o escrita na 0480) â€”, e a
--    tabela nasce VAZIA de propÃ³sito: nÃ£o se inventa dado de LGPD para um mÃ³dulo que nÃ£o pediu.
-- 2. `fn_lgpd_redigir_secoes_de_modulo()` â€” gatilho `after update of is_anonymized` em
--    `contacts`, a MESMA porta das 0174/0184/0210/0391: a virada `false â†’ true` Ã© por onde os
--    DOIS caminhos de anonimizaÃ§Ã£o passam (a cascata e `fn_lgpd_anonymize_contact`), entÃ£o nÃ£o
--    hÃ¡ caminho que escape por construÃ§Ã£o.
-- 3. O `to_regclass` antes de CADA seÃ§Ã£o â€” mÃ³dulo nÃ£o instalado = tabela ausente = `continue`,
--    sem erro, em qualquer instalaÃ§Ã£o. Ã‰ literalmente o que a ADR pede e o que a cascata
--    nomeada por tabela nÃ£o pode dar.
--
-- â”€â”€ Por que SECURITY DEFINER sem parÃ¢metro (D4) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- O gatilho roda com a sessÃ£o de quem atualizou `contacts`; sem `definer`, um caminho que
-- atualiza como `authenticated` nÃ£o teria permissÃ£o de escrever na tabela de outro mÃ³dulo por
-- cima da RLS. Sem PARÃ‚METRO nenhum (nada de tabela, SQL ou organizaÃ§Ã£o vindo de fora), o efeito
-- Ã© fixo e conhecido: a mesma argumentaÃ§Ã£o da D4 para a provisionadora. `execute` revogado de
-- `public`, `anon` e `authenticated` â€” gatilho nÃ£o precisa de grant para disparar, e sem argumento
-- de organizaÃ§Ã£o esta funÃ§Ã£o fica fora da rÃ©gua de `definer-membership-varredura` por construÃ§Ã£o.
--
-- â”€â”€ Coluna declarada que nÃ£o existe: ERRO ALTO, nÃ£o redaÃ§Ã£o pela metade â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- DeclaraÃ§Ã£o errada da migration do mÃ³dulo levanta `modulo_secao_invalida` nomeando mÃ³dulo e
-- tabela. Silenciar aqui seria entregar ANONIMIZAÃ‡ÃƒO COM SUCESSO com a pessoa legÃ­vel â€” o mesmo
-- modo de falha que a LGPD nÃ£o tolera em lugar nenhum. O invariante da D8 mede os dois lados.
--
-- ReaplicÃ¡vel (tripla da casa): `if not exists`, `create or replace`, `drop trigger if exists`.
-- O apÃªndice do `baseline.sql` entra ANTES do bloco da `VARREDURA anon` (0116), que proÃ­be
-- `create function` depois dela â€” ver `tests/unit/varredura-anon-e-o-ultimo-bloco.test.ts`.

create table if not exists public.modulo_secoes_lgpd (
  modulo text not null check (modulo ~ '^[a-z][a-z0-9_]{1,40}$'),
  tabela text not null check (tabela ~ '^[a-z][a-z0-9_]{1,40}$'),
  -- Predicado que liga a linha da tabela ao contato, com $1 = organization_id e
  -- $2 = contact_id. Vai para o `execute` via `using`: nenhum valor de contato entra no texto.
  ligacao text not null,
  colunas text[] not null default '{}'::text[],
  colunas_rotulo text[] not null default '{}'::text[],
  primary key (modulo, tabela)
);
comment on table public.modulo_secoes_lgpd is
  'SeÃ§Ãµes de LGPD que um MÃ“DULO opcional declara (ADR-0002, D8). Escrito sÃ³ pela migration do mÃ³dulo; fn_lgpd_redigir_secoes_de_modulo lÃª com to_regclass e PULA a seÃ§Ã£o cuja tabela nÃ£o existe (mÃ³dulo nÃ£o instalado).';

alter table public.modulo_secoes_lgpd enable row level security;
-- Fechada tambÃ©m para `service_role`: o gatilho abaixo Ã© `definer` de dono `postgres` e
-- executa o `tabela`/`ligacao` gravados aqui, e o default ACL daria GRANT ALL a ele.
revoke all on public.modulo_secoes_lgpd from public, anon, authenticated, service_role;

create or replace function public.fn_lgpd_redigir_secoes_de_modulo()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $f$
declare
  s record;
  v_rel oid;
  v_sets text;
  v_nulos text;
  v_rotulos text;
  v_rotulo text := 'Cliente Anonimizado #' || substring(new.id::text from 1 for 8);
begin
  -- O gatilho jÃ¡ tem `when (new.is_anonymized and not old.is_anonymized)`, e a guarda aqui Ã© a
  -- mesma: uma funÃ§Ã£o que tambÃ©m serve de alvo de `execute` nÃ£o deve depender do chamador.
  if not (new.is_anonymized and not old.is_anonymized) then
    return null;
  end if;

  for s in
    select modulo, tabela, ligacao, colunas, colunas_rotulo
      from public.modulo_secoes_lgpd
     order by modulo, tabela
  loop
    v_rel := to_regclass(format('public.%I', s.tabela));

    -- D8, o ponto central: mÃ³dulo nÃ£o instalado nÃ£o existe aqui, e a anonimizaÃ§Ã£o de um
    -- contato NUNCA pode falhar por causa de mÃ³dulo que ninguÃ©m ligou.
    if v_rel is null then
      continue;
    end if;

    if btrim(s.ligacao) = '' or (cardinality(s.colunas) = 0 and cardinality(s.colunas_rotulo) = 0) then
      raise exception 'modulo_secao_invalida: %/% declara ligaÃ§Ã£o vazia ou sem coluna', s.modulo, s.tabela;
    end if;

    if exists (
      select 1
        from unnest(s.colunas || s.colunas_rotulo) as c(coluna)
       where not exists (
         select 1
           from pg_attribute a
          where a.attrelid = v_rel
            and a.attname = c.coluna
            and a.attnum > 0
            and not a.attisdropped
       )
    ) then
      raise exception 'modulo_secao_invalida: %/% tem coluna declarada que nÃ£o existe', s.modulo, s.tabela;
    end if;

    select string_agg(format('%I = null', c), ', ' order by c) into v_nulos
      from unnest(s.colunas) as c;
    select string_agg(format('%I = %L', c, v_rotulo), ', ' order by c) into v_rotulos
      from unnest(s.colunas_rotulo) as c;
    v_sets := concat_ws(', ', v_nulos, v_rotulos);

    -- SQL dinÃ¢mico: o NOME da tabela vem da declaraÃ§Ã£o (e jÃ¡ passou pelo to_regclass acima),
    -- o predicado vai literal e os dois valores entram por `using`.
    execute format('update public.%I set %s where (%s)', s.tabela, v_sets, s.ligacao)
      using new.organization_id, new.id;
  end loop;

  return null;
end $f$;

revoke execute on function public.fn_lgpd_redigir_secoes_de_modulo() from public, anon, authenticated;

drop trigger if exists trg_lgpd_secoes_de_modulo on public.contacts;
create trigger trg_lgpd_secoes_de_modulo
  after update of is_anonymized on public.contacts
  for each row
  when (new.is_anonymized and not old.is_anonymized)
  execute function public.fn_lgpd_redigir_secoes_de_modulo();

-- ---- ExclusÃ£o de contato com turno de follow-up: ficha inteira (migration 0488) ----
-- Issue #1862: a rota apagava `messages`, `conversations` e `contacts` em trÃªs
-- chamadas separadas, e o `contacts` era recusado com 42501 pelo gatilho de
-- follow-up quando a ficha tinha turno â€” histÃ³rico apagado, ficha ficando.
-- A funÃ§Ã£o nova abaixo Ã© a chamada ÃšNICA que a rota passa a fazer: as trÃªs
-- saem numa transaÃ§Ã£o sÃ³. SECURITY INVOKER de propÃ³sito, como os trÃªs DELETE
-- separados que ela substitui: a RLS de quem chama continua valendo, e
-- `p_organization_id` fecha a linha por dentro â€” sem service role.
-- O conserto da outra metade (a guarda do gatilho, `pg_trigger_depth() > 1`)
-- estÃ¡ no bloco da 0224, EDITADO NO LUGAR, porque Ã© a MESMA funÃ§Ã£o.
create or replace function public.fn_apagar_contato_com_historico(
  p_contact_id uuid,
  p_organization_id uuid
)
returns boolean
language plpgsql
volatile
security invoker
set search_path to 'public', 'pg_temp'
as $$
begin
  -- RESTRICT da #752: o histÃ³rico sai antes da ficha, na mesma transaÃ§Ã£o.
  delete from public.messages
   where contact_id = p_contact_id
     and organization_id = p_organization_id;

  delete from public.conversations
   where contact_id = p_contact_id
     and organization_id = p_organization_id;

  delete from public.contacts
   where id = p_contact_id
     and organization_id = p_organization_id;

  -- `found` Ã© do DELETE da ficha: false = a ficha nÃ£o estava acessÃ­vel para quem
  -- chamou (outra organizaÃ§Ã£o, RLS, corrida) â€” a rota devolve 404 nesse caso.
  return found;
end;
$$;

-- FunÃ§Ã£o nova em `public` nasce exposta (ALTER DEFAULT PRIVILEGES do dump):
-- o revoke tira anon e o grant deixa sÃ³ quem a rota usa.
revoke execute on function public.fn_apagar_contato_com_historico(uuid, uuid) from public, anon;
grant  execute on function public.fn_apagar_contato_com_historico(uuid, uuid) to authenticated, service_role;

notify pgrst, 'reload schema';

