comment on column public.catalog_products.fotos is
  'Caminhos em storage/catalog-photos, sempre <organization_id>/<id>/<uuid>.<jpg|png>. A ordem Ã© a da tela e a primeira Ã© a capa. Escrito sÃ³ por app/api/v1/products/[id]/fotos.';
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('catalog-photos', 'catalog-photos', false, 5242880, array['image/jpeg', 'image/png'])
